after:
/* Typed annotations remain distinguishable by borders and labels as well as colour. */
#<MOUNT> .uf-chip-unresolved {
  background:#ECFDF5; color:#14532D; border:1px dashed #4D7C0F;
}
#<MOUNT> .uf-unknown-values {
  margin:12px 0; padding:8px 12px; border:1px dashed #4D7C0F;
  border-radius:8px; color:#14532D; background:#ECFDF5;
}
#<MOUNT> .uf-unknown-values summary { cursor:pointer; font-size:12px; }
#<MOUNT> .uf-unknown-value-list { display:flex; flex-direction:column; gap:6px; margin-top:8px; }
#<MOUNT> .uf-value-reason { white-space:normal; overflow-wrap:anywhere; border-radius:4px; }
#<MOUNT> .uf-unknown-value-group { font-size:11px; line-height:1.5; }
#<MOUNT> .uf-unknown-value-group > div { margin-top:5px; }
#<MOUNT> .uf-value-paths { font-size:10px; white-space:pre-wrap; overflow-wrap:anywhere; max-height:320px; overflow:auto; }
#<MOUNT> .uf-chip-class_default {
  background:#EFF6FF; color:#1E3A8A; border:1px solid #60A5FA;
}
#<MOUNT> .uf-chip-symbolic {
  background:#FAF5FF; color:#581C87; border:3px double #A855F7;
}
#<MOUNT> .uf-chip-pending_design {
  background:#FFFBEB; color:#78350F; border:1px dotted #B45309;
  border-radius:4px;
}
